{
  "findings": [
    {
      "check_id": "CKV_AWS_126",
      "title": "Ensure that detailed monitoring is enabled for EC2 instances",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "Detailed monitoring is not enabled for this EC2 instance. Without it, you may lack critical performance metrics for monitoring and troubleshooting."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "Instance Metadata Service Version 1 (IMDSv1) is less secure than IMDSv2 and can be exploited in SSRF attacks. IMDSv2 should be enforced."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The root EBS volume for this EC2 instance is not explicitly encrypted. Unencrypted volumes can expose sensitive data if compromised."
    },
    {
      "check_id": "CKV2_AWS_41",
      "title": "Ensure an IAM role is attached to EC2 instance",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "This EC2 instance does not have an IAM role attached. Without an IAM role, the instance cannot securely access AWS services or resources."
    }
  ],
  "patched_code": "resource "aws_instance" "MyFirstInstnace" {
  ami           = lookup(var.AMIS, var.AWS_REGION)
  instance_type = "t2.micro"
  availability_zone = "us-east-2a"
  key_name      = aws_key_pair.levelup_key.key_name
  vpc_security_group_ids = [aws_security_group.allow-levelup-ssh.id]
  subnet_id = aws_subnet.levelupvpc-public-1.id

  monitoring = true

  metadata_options {
    http_tokens = "required"
    http_endpoint = "enabled"
  }

  root_block_device {
    encrypted = true
  }

  iam_instance_profile = aws_iam_instance_profile.my_instance_profile.name
}

resource "aws_iam_instance_profile" "my_instance_profile" {
  name = "my-instance-profile"
  role = aws_iam_role.my_instance_role.name
}

resource "aws_iam_role" "my_instance_role" {
  name = "my-instance-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "ec2.amazonaws.com"
        },
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "my_instance_policy" {
  name = "my-instance-policy"
  role = aws_iam_role.my_instance_role.id
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Action = ["s3:ListBucket"],
        Resource = ["arn:aws:s3:::example-bucket"]
      }
    ]
  })
}",
  "fix_summary": "Enabled detailed monitoring for the EC2 instance, enforced IMDSv2 for metadata access, ensured the root EBS volume is encrypted, and attached an IAM role with a minimal policy to the instance."
}
